import rclpy
from rclpy.node import Node
from eai_manipulator_msgs.msg import WarnAndErrorInfo
from std_msgs.msg import Header
import os
import datetime


class LogAnalyser(Node):
    """订阅 /manipulator/warn_and_error_info 话题的节点"""

    def __init__(self):

        self.dedup_timeout = 3.0
        super().__init__('log_analyser')
        
        # 设置日志文件路径
        self.log_dir = os.path.expanduser("/home/ubuntu/XARM_logs")
        os.makedirs(self.log_dir, exist_ok=True)
        
        # 创建日志文件
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        self.log_file_path = os.path.join(self.log_dir, f"xarm_warn_error_{timestamp}.log")
        
        # 读取 /home/ubuntu/XARM/VERSION 文件内容（只读取一次，并写入日志文件）
        version_path = "/home/ubuntu/XARM/VERSION"
        if os.path.exists(version_path):
            try:
                with open(version_path, 'r', encoding='utf-8') as f:
                    version_content = f.read()
                self.get_logger().info("VERSION 文件内容:\n" + version_content)
                with open(self.log_file_path, 'a', encoding='utf-8') as log_f:
                    log_f.write('xArm 版本号: ')
                    log_f.write(version_content)
            except Exception as e:
                self.get_logger().warn(f"读取 VERSION 文件失败: {e}")
                with open(self.log_file_path, 'a', encoding='utf-8') as log_f:
                    log_f.write(f"\n读取 VERSION 文件失败: {e}\n")
        else:
            with open(self.log_file_path, 'a', encoding='utf-8') as log_f:
                log_f.write(f"\nxArm 版本号: unknown\n")

        
        # 读取 /home/ubuntu/XARM/commit_info.txt 文件内容（只读取一次，并写入日志文件）
        commit_info_path = "/home/ubuntu/XARM/commit_info.txt"
        if os.path.exists(commit_info_path):
            try:
                with open(commit_info_path, 'r', encoding='utf-8') as f:
                    commit_info_content = f.read()
                self.get_logger().info("commit_info.txt 内容:\n" + commit_info_content)
                with open(self.log_file_path, 'a', encoding='utf-8') as log_f:
                    log_f.write('\n===== commit_info.txt 内容 =====\n')
                    log_f.write(commit_info_content)
                    log_f.write('\n===== END OF commit_info.txt =====\n')
            except Exception as e:
                self.get_logger().warn(f"读取 commit_info.txt 失败: {e}")
                with open(self.log_file_path, 'a', encoding='utf-8') as log_f:
                    log_f.write(f"\n读取 commit_info.txt 失败: {e}\n")
        else:
            self.get_logger().warn(f"文件不存在: {commit_info_path}")
            with open(self.log_file_path, 'a', encoding='utf-8') as log_f:
                log_f.write(f"\n文件不存在: {commit_info_path}\n")
        # 创建订阅者
        self.subscription = self.create_subscription(
            WarnAndErrorInfo,
            '/manipulator/warn_and_error_info',
            self.warn_error_callback,
            10
        )
        
        self.get_logger().info(f'LogAnalyser 节点已启动，正在监听 /manipulator/warn_and_error_info 话题')
        self.get_logger().info(f'日志文件保存位置: {self.log_file_path}')


        
        # 创建一个软连接 last 指向当前日志文件
        last_link = os.path.join(self.log_dir, "last_warn_error.log")
        try:
            if os.path.islink(last_link) or os.path.exists(last_link):
                os.remove(last_link)
            os.symlink(self.log_file_path, last_link)
            self.get_logger().info(f'已创建软连接: {last_link} -> {self.log_file_path}')
        except Exception as e:
            self.get_logger().warn(f'创建软连接失败: {e}')
        with open(self.log_file_path, 'a', encoding='utf-8') as f:
            f.write(f'LogAnalyser 节点已启动，正在监听 /manipulator/warn_and_error_info 话题' + '\n')
            f.write(f'去重设置: {self.dedup_timeout}秒内相同消息将被去重' + '\n')
        
        self.last_source = None
        self.last_code = None
        # 创建定时器，每10秒重置last_source和last_code为None
        self.timer = self.create_timer(self.dedup_timeout, self.reset_last)

    def reset_last(self):
        """定时重置last_source和last_code为None"""
        self.last_source = None
        self.last_code = None


    def warn_error_callback(self, msg: WarnAndErrorInfo):
        """处理接收到的警告和错误信息"""
        # 格式化时间戳
        timestamp = msg.header.stamp
        time_str = f"{timestamp.sec}.{timestamp.nanosec:09d}"
        
        # 格式化日志消息
        log_message = f"[{time_str}] {msg.level.upper()} - 来源: {msg.source}, 代码: {msg.code}, 信息: {msg.info}"
        if msg.source == self.last_source and msg.code == self.last_code:
            return
        self.last_source = msg.source
        self.last_code = msg.code
        # 写入文件
        with open(self.log_file_path, 'a', encoding='utf-8') as f:
            f.write(log_message + '\n')
        
        # # 根据级别选择不同的控制台日志输出
        # if msg.level.lower() == 'error':
        #     self.get_logger().error(log_message)
        # elif msg.level.lower() == 'warning' or msg.level.lower() == 'warn':
        #     self.get_logger().warn(log_message)
        # elif msg.level.lower() == 'info':
        #     self.get_logger().info(log_message)
        # else:
        #     self.get_logger().info(log_message)


def main(args=None):
    """主函数"""
    rclpy.init(args=args)
    
    # 创建订阅节点
    warn_error_subscriber = LogAnalyser()
    
    try:
        # 开始旋转节点
        rclpy.spin(warn_error_subscriber)
    except KeyboardInterrupt:
        pass
    finally:
        # 清理资源
        warn_error_subscriber.destroy_node()
        # launch/system 可能已经触发过 shutdown，这里避免重复调用
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == '__main__':
    main()
